<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="cm-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="cm-opbar"><button type="button" @click="emit('back')">←</button><strong>29CM</strong><nav><button type="button" data-testid="shopping-open-service" @click="emit('open-service')">CARE</button><button type="button" @click="emit('open-orders')">ARCHIVE</button><button type="button" @click="emit('open-cart')">BAG <b v-if="cartQuantity">{{ cartQuantity }}</b></button></nav></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="cm-bag"><header><span>BAG / CONSIDERED OBJECTS</span><h1>{{ l('把选择放在一起，再决定','Keep the objects together before deciding') }}</h1><p>{{ l('购物袋是一张编辑清单，不是催促结算的倒计时。','The bag is an editorial checklist, not a checkout countdown.') }}</p></header><div v-if="!cartItems.length" class="cm-empty">NO OBJECTS IN THE BAG</div><div v-else class="cm-bag-layout"><section><article v-for="(line,index) in cartItems" :key="line.productId"><span class="cm-num">{{ String(index+1).padStart(2,'0') }}</span><div class="cm-object"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i></div><div><small>OBJECT NOTE</small><strong>{{ productDisplayTitle(line.product) }}</strong><b>{{ formatOrderItemSubtotal({ ...line, unitPriceCents:line.product.priceCents, currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><span>REVIEW / {{ cartQuantity }} OBJECTS</span><strong>{{ cartTotalLabel }}</strong><blockquote>{{ l('“真正留下的，应该经得起重复观看。”','“What remains should reward repeated attention.”') }}</blockquote><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" /> GIFT EDIT</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">MANUAL RECIPIENT</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" placeholder="RECIPIENT NAME" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">CREATE ORDER ARCHIVE →</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="cm-archive"><header><div><span>ARCHIVE / PURCHASED OBJECTS</span><h1>{{ l('选择留下的记录','An archive of chosen objects') }}</h1></div><button @click="emit('open-logistics')">DELIVERY JOURNAL</button></header><div v-if="!orders.length" class="cm-empty">ARCHIVE IS EMPTY</div><div v-else class="cm-archive-grid"><article v-for="(order,index) in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><b>{{ String(index+1).padStart(2,'0') }}</b><span>{{ formatLogisticsDate(order.createdAt) }}</span><h2>{{ order.items.map(item=>item.title).join(' / ') }}</h2><p>{{ order.itemCount }} OBJECTS / {{ formatOrderTotal(order) }}</p><footer><em>{{ orderStatusLabel(order.status) }}</em><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">OPEN DOSSIER</button><button @click="emit('delete-order',order.id)">×</button></footer></article></div></section>
    <section v-else-if="pageKey==='logistics'" class="cm-journal" data-testid="shopping-logistics-panel"><header><span>DELIVERY JOURNAL</span><h1>{{ l('物件正在去往哪里','Where the objects are going') }}</h1><button @click="emit('open-orders')">BACK TO ARCHIVE</button></header><article v-for="(row,index) in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><b>ENTRY {{ String(index+1).padStart(2,'0') }}</b><div><span>{{ formatLogisticsDate(row.suggestedAt) }}</span><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><em :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</em><small v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ logisticsEventTypeLabel(row.latestEvent.type) }} / {{ row.latestEvent.trackingCode }}</small><button :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">READ ORDER DOSSIER →</button></div></article><div v-if="!logisticsRows.length" class="cm-empty">NO DELIVERY ENTRIES</div></section>
    <section v-else-if="selectedOrder" class="cm-dossier" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">← ARCHIVE</button><span>OBJECT DOSSIER / {{ selectedOrder.id }}</span><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="cm-dossier-cover"><div><p>TOTAL VALUE</p><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><h1>{{ selectedOrder.items.map(item=>item.title).join(' / ') }}</h1><span>{{ selectedOrder.itemCount }} OBJECTS</span></section><section class="cm-dossier-items"><article v-for="(item,index) in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>{{ String(index+1).padStart(2,'0') }}</span><h2>{{ item.title }}</h2><p>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item,quantity:1 }) }}</p><strong>{{ formatOrderItemSubtotal(item) }}</strong></article></section><section class="cm-dossier-timeline" data-testid="shopping-order-detail-timeline"><p>DELIVERY NOTES</p><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><span>{{ formatLogisticsDate(event.createdAt) }}</span><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary||event.title }}</p></article><div v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO RECORDED DELIVERY NOTES</div></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COMPLETE ARCHIVE</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE RECORD</button></footer></section>
  </main>
